window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"J_wnDKwXMKg","speaker":"Taneti Maamau","role":"President","country":"Kiribati","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=J_wnDKwXMKg","date":"20260925","title":"🇰🇮 Kiribati - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":979,"words":1590,"counts":{"claims":26,"promises":5,"attacks":0},"topics":[{"topic":"Kiribati partnerships","share":0.0777,"seconds":76},{"topic":"Kiribati women","share":0.0765,"seconds":75},{"topic":"Nuclear disarmament","share":0.0747,"seconds":73},{"topic":"Sustainable development","share":0.074,"seconds":72},{"topic":"Ocean governance","share":0.0721,"seconds":71},{"topic":"Micronian Games","share":0.0708,"seconds":69},{"topic":"Climate justice","share":0.0698,"seconds":68},{"topic":"Climate change","share":0.0664,"seconds":65},{"topic":"Kiribati renewable energy","share":0.0663,"seconds":65},{"topic":"UNGA 81st session","share":0.0641,"seconds":63},{"topic":"Micronesia infrastructure","share":0.064,"seconds":63},{"topic":"UN reform","share":0.0637,"seconds":62},{"topic":"Kiribati education","share":0.0634,"seconds":62},{"topic":"Ocean sustainability","share":0.0631,"seconds":62},{"topic":"Ceremony","share":0.0336,"seconds":33}],"timeline":[[1,72,null],[72,135,"UNGA 81st session"],[137,199,"UN reform"],[200,262,"Ocean sustainability"],[264,334,"Ocean governance"],[336,401,"Climate change"],[402,467,"Kiribati renewable energy"],[468,537,"Climate justice"],[538,610,"Sustainable development"],[612,688,"Kiribati partnerships"],[689,751,"Kiribati education"],[752,827,"Kiribati women"],[828,898,"Micronian Games"],[899,972,"Nuclear disarmament"],[973,1036,"Micronesia infrastructure"],[1036,1069,"Ceremony"]],"stances":{"UNGA 81st session":"Taneti Maamau congratulates the President of the General Assembly and pledges full support for their leadership.","UN reform":"Taneti Maamau states that trust in the United Nations cannot be restored by words alone and must instead be strengthened through accountability and tangible results.","Ocean sustainability":"Taneti Maamau states that Kiribati's economy and way of life depend on healthy marine resources and calls for increased partnership to achieve Sustainable Development Goal 14.","Ocean governance":"Taneti Maamau states that ocean pressures are increasing due to climate change and fishing activities, highlights the significance of the biodiversity agreement, and calls for collective action.","Climate change":"Taneti Maamau states that climate change is a pressing challenge for Kiribati and outlines national investments in resilience and adaptation.","Kiribati renewable energy":"Taneti Maamau states that Kiribati aims to build a wealthy and healthy nation with dignity by increasing investment in renewable energy to reduce reliance on fossil fuels, while calling for international support and climate finance.","Climate justice":"Taneti Maamau affirms that the ICJ advisory opinion establishes binding duties for states to reduce greenhouse gases and welcomes locally driven climate resilience initiatives.","Sustainable development":"Taneti Maamau asserts that partnership is essential for achieving the goals of the 2030 agenda and reaffirms Kiribati's commitment to it through voluntary national reviews.","Kiribati partnerships":"Taneti Maamau states that Kiribati values its diplomatic relations and has convened a development partners forum to strengthen ties and showcase projects.","Kiribati education":"Taneti Maamau states that Kiribati is committed to expanding access to quality, inclusive, and relevant education while strengthening skills development and vocational training.","Kiribati women":"Taneti Maamau states that Kiribati is committed to gender equality, has secured a seat on the Commission on the Status of Women, and will expand opportunities for women while providing youth with education and employment.","Micronian Games":"Taneti Maamau states that Kiribati intends to host the 2030 Micronian Games to leave a legacy for young people and invites partners to join this effort.","Nuclear disarmament":"Taneti Maamau states that Kiribati remains committed to advancing treaties and establishing a trust fund for nuclear weapons victims while highlighting the ongoing human and environmental legacy of nuclear testing in the Pacific.","Micronesia infrastructure":"Taneti Maamau states that the Micronian cable has improved connectivity but also created vulnerabilities due to limited redundancy and technical capacity, while noting broader digital threats facing island states.","Ceremony":"Taneti Maamau extends traditional blessings and expresses gratitude to the United Nations, its members, staff, and specific officials."},"claims":[{"t":94,"quote":"On behalf of the government and the people of Kiribas, I extend our warmest congratulations to you, Mr. President, on your election to preside and lead this 81st session of the United Nations General Assembly.","topic":"UNGA 81st session","kind":"fact"},{"t":137,"quote":"Human rights continue to be violated. Humanitarian crisis persist. Development gains are being reversed in many parts of the world.","topic":"UN reform","kind":"fact"},{"t":152,"quote":"Inequality remains entrenched while climate change places additional pressure on the already confronting significant development challenges.","topic":"UN reform","kind":"fact"},{"t":215,"quote":"Gibbus is an ocean We are a big ocean sustainable state.","topic":"Ocean sustainability","kind":"fact"},{"t":223,"quote":"Our economy, food security, livelihoods, culture, and the way of life depend on healthy, sustainable marine resources.","topic":"Ocean sustainability","kind":"fact"},{"t":264,"quote":"The 2026 sustainable development goals report reminds us that our oceans and fisheries continue to face mounting pressures from over fishing, illegal, unreported and unregulated fishing, pollution, warming and acidification.","topic":"Ocean governance","kind":"fact"},{"t":285,"quote":"The entry into force of the biod diversity beyond national jurisdiction agreement marks an important step towards stronger and more equitable ocean governance.","topic":"Ocean governance","kind":"fact"},{"t":343,"quote":"Sea sea level rise, coastal erosion, saltwater intrusion and extreme weather events continue to pressure to place pressure on our communities, infrastructure, water security and livelihoods.","topic":"Climate change","kind":"fact"},{"t":361,"quote":"The intergovernmental panel on climate change six assessment report reinforces the agency of these challenges and particularly the risk faced by small island states through our long-term national development vision the gibbas vision for 20 years","topic":"Climate change","kind":"fact"},{"t":402,"quote":"Our objective is clear to continue building a wealthy, healthy and peaceful Kiribus where our people can live with dignity","topic":"Kiribati renewable energy","kind":"fact"},{"t":417,"quote":"Renewable energy is increasingly important to Kiriba's developments and energy access","topic":"Kiribati renewable energy","kind":"fact"},{"t":468,"quote":"The International Court of Justice Advisory Opinion on Climate Change advances climate justice by affirming that all states have binding duties to protect the climate system and achieve deep rapid and sustained greenhouse gas reductions consistent with limiting warming to 1.5° C.","topic":"Climate justice","kind":"fact"},{"t":504,"quote":"The Pacific Resilience Facility is a Pacific Pacific owned mechanism that strengthens the region's capacity to finance climate and disaster resilience.","topic":"Climate justice","kind":"fact"},{"t":562,"quote":"Gilipus reaffirms his support for frameworks that embody the spirit of partnership including the Antigu and Barbuta agenda for seats a best and the Pacific for the future which provide important foundations for strengthened international cooperation solidarity and collect collective action as the 2030 agenda enters it final is partnership must remain central to accelerating SG progress.","topic":"Sustainable development","kind":"fact"},{"t":598,"quote":"Gilibus Gilibus recently presented its second voluntary national review Vietn reaffirming our commitments to the 2030 agenda.","topic":"Sustainable development","kind":"fact"},{"t":632,"quote":"This year following the submission of our second VNRA, my government convened its first development partners forum on Christmas Island or Christmas Island","topic":"Kiribati partnerships","kind":"fact"},{"t":644,"quote":"which we highly value as the world's largest coral at all and the first island to see each new day's sunrise","topic":"Kiribati partnerships","kind":"fact"},{"t":698,"quote":"We call the Christmas Partnership Accord Mr. President, ultimately development depends on people, our most valuable resource, making education a vital investment.","topic":"Kiribati education","kind":"fact"},{"t":715,"quote":"Gilas is committed to expanding access to quality, inclusive, relevant education while strengthening skills, development, skills development, vocational training.","topic":"Kiribati education","kind":"self_credit"},{"t":778,"quote":"Our election earlier this year to the commission on the status of women. The first time Kibas has secured a seat on this UN body is a significant milestone reflecting our determination to advance women's rights nationally and globally.","topic":"Kiribati women","kind":"fact"},{"t":828,"quote":"Gilibas will lost the 2030 Micronian Games which we intend to use to leave a lasting legacy for our young people.","topic":"Micronian Games","kind":"fact"},{"t":859,"quote":"Mr. President, Kilibus is a peaceful nation.","topic":"Micronian Games","kind":"fact"},{"t":928,"quote":"Our region bears the human and environmental legacy of nuclear testing.","topic":"Nuclear disarmament","kind":"fact"},{"t":951,"quote":"As co-chairs with Kazakhstan of the recent international meeting on victim assistance and environmental remediation","topic":"Nuclear disarmament","kind":"self_credit"},{"t":981,"quote":"The his Micronian cable landed in Tarawa last year connecting Gilibas with NU and the federated state of Micronia transforming our connectivity and digital environment.","topic":"Micronesia infrastructure","kind":"fact"},{"t":995,"quote":"However, it also creates vulnerabilities with limited redundancy and technical capacity.","topic":"Micronesia infrastructure","kind":"fact"}],"promises":[{"t":113,"quote":"Gibbus assures you of our full support and cooperation as you undertake this important responsibility.","topic":"UNGA 81st session","kind":"promise"},{"t":799,"quote":"We will expand opportunities, prevent violence, and promote women's economic empowerment and leadership.","topic":"Kiribati women","kind":"promise"},{"t":813,"quote":"We must provide them with education, employment, skills, technology, leadership opportunities and spaces where they can contribute and one of those spaces is sport.","topic":"Kiribati women","kind":"promise"},{"t":839,"quote":"We invite our regional and international partners to join us in this endeavor for kibbas on peace and security.","topic":"Micronian Games","kind":"promise"},{"t":939,"quote":"We remain committed to advancing the treaties and human humanitarian objectives and establishing an international trust fund for nuclear weapons victims.","topic":"Nuclear disarmament","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":null,"text":"The assembly will hear an address by his excellency teneti ma maauo, president and minister for foreign affairs and immigration of the republic of Kiribati. I request protocol to escort his excellency and invite him to address the Mr."},{"t":72,"topic":"UNGA 81st session","text":"President, Mr. Secretary General, the Excellencies, distinguished heads of states and ladies and gentlemen, in the name of Almighty God in whom we place our trust. On behalf of the government and the people of Kiribas, I extend our warmest congratulations to you, Mr. President, on your election to preside and lead this 81st session of the United Nations General Assembly. Gibbus assures you of our full support and cooperation as you undertake this important responsibility. Mr. President, we meet today at a difficult moment. Conflicts continue to claim lives and displace communities."},{"t":137,"topic":"UN reform","text":"Human rights continue to be violated. Humanitarian crisis persist. Development gains are being reversed in many parts of the world. Inequality remains entrenched while climate change places additional pressure on the already confronting significant development challenges. It is therefore fitting that the theme of this 81st session is restoring restoring trust managing transformation a united nations that delivers for This theme is both timely and relevant. Trust cannot be restored by words alone. It must be strengthened through accountability and results that improve the lives of our people."},{"t":200,"topic":"Ocean sustainability","text":"For Gilibas, the theme reaffirms our shared duty to strengthen the United Nations and ensure it serves everyone. Mr. President, Gibbus is an ocean We are a big ocean sustainable state. Our economy, food security, livelihoods, culture, and the way of life depend on healthy, sustainable marine resources. Sustainable management is essential to our long-term developments and we call for increased efforts and partnership partnerships to have agreeable progable progress towards SG14 which is conserve and sustainably use sustainably used oceans, seas and marine resources for sustainable development."},{"t":264,"topic":"Ocean governance","text":"The 2026 sustainable development goals report reminds us that our oceans and fisheries continue to face mounting pressures from over fishing, illegal, unreported and unregulated fishing, pollution, warming and acidification. The entry into force of the biod diversity beyond national jurisdiction agreement marks an important step towards stronger and more equitable ocean governance. Gilibus is proud to have signed and ratified this agreement and calls on member states to recognize the vital importance of our shared oceans and to work collectively to translate the agreement's historic ambition into histo meaningful global Mr. President, the sustainability of our ocean and fisheries is closely linked to the changing climate and the pressures we face on our marine resources are increasingly compounded by its impact."},{"t":336,"topic":"Climate change","text":"Climate remains one of the most pressing challenges to our developments and the way of life. Sea sea level rise, coastal erosion, saltwater intrusion and extreme weather events continue to pressure to place pressure on our communities, infrastructure, water security and livelihoods. The intergovernmental panel on climate change six assessment report reinforces the agency of these challenges and particularly the risk faced by small island states through our long-term national development vision the gibbas vision for 20 years our national priorities and the most politics we continue to invest in resilience infrastructure water security, coastal protection, disaster preparedness, renew renewable energy and communitybased adaptation."},{"t":402,"topic":"Kiribati renewable energy","text":"Our objective is clear to continue building a wealthy, healthy and peaceful Kiribus where our people can live with dignity, in peace and with Renewable energy is increasingly important to Kiriba's developments and energy access. We therefore see greater investment in renewable energy as an important opportunity to reduce our reliance on imported fossil fuels and strengthen the resilience and sustainability of our energy sector. But national action must be matched by international action. We call for greater ambition, stronger support for adaptation and climate finance that is adequate, predictable and accessible, particularly for small island developing states. Gilas recognizes the importance of international law in addressing climate change."},{"t":468,"topic":"Climate justice","text":"The International Court of Justice Advisory Opinion on Climate Change advances climate justice by affirming that all states have binding duties to protect the climate system and achieve deep rapid and sustained greenhouse gas reductions consistent with limiting warming to 1.5° C. We welcome growing recognition that climate resilience must be locally honed and driven. The Pacific Resilience Facility is a Pacific Pacific owned mechanism that strengthens the region's capacity to finance climate and disaster resilience. The Pacific's co-hosting of COP 31 with Turkey later this year further demonstrates the value of local action. These initiatives also show that strong genuine partnerships can sustain locally led development."},{"t":538,"topic":"Sustainable development","text":"Mr. President, partnership continues to shape international cooperation as we believe that we are stronger when we work together. At a time when multilateralism faces growing challenges, partnership remains one of our most powerful affirmations of what we can achieve collectively. Gilipus reaffirms his support for frameworks that embody the spirit of partnership including the Antigu and Barbuta agenda for seats a best and the Pacific for the future which provide important foundations for strengthened international cooperation solidarity and collect collective action as the 2030 agenda enters it final is partnership must remain central to accelerating SG progress. Gilibus Gilibus recently presented its second voluntary national review Vietn reaffirming our commitments to the 2030 agenda."},{"t":612,"topic":"Kiribati partnerships","text":"We value our longstanding diplomatic relations with traditional partners and welcome countries seeking new partnerships based on mutual respect, shared interest, transparency, sovereign equality, and respect for our national priorities. This year following the submission of our second VNRA, my government convened its first development partners forum on Christmas Island or Christmas Island, which we highly value as the world's largest coral at all and the first island to see each new day's sunrise. This forum strengthened partnerships between Gilipas and its development partners and showcased two flagship projects critical to accelerating economic growth and sustainable development. Participants included Australia, the the People's Republic of China, the European Union, New Zealand, Japan, the United States of America, the World Bank, the Asian Development Bank, and the UN agencies."},{"t":689,"topic":"Kiribati education","text":"We thank our partners and look forward to advancing our shared interest under the forums outcome document. We call the Christmas Partnership Accord Mr. President, ultimately development depends on people, our most valuable resource, making education a vital investment. Gilas is committed to expanding access to quality, inclusive, relevant education while strengthening skills, development, skills development, vocational training. digital learning and opportunities for young people. Health is equally fundamental. We continue to strengthen our health systems across our widely dispersed and remote silence, improve access to essential services, and address both communicable and non-communicable diseases."},{"t":752,"topic":"Kiribati women","text":"Healthy and educated population is the foundation upon which every other national priority rest. Mr. President, we cannot speak about development with without speaking about women and youth. Gilibus remains committed to gender equality and empowering women and girls. Our election earlier this year to the commission on the status of women. The first time Kibas has secured a seat on this UN body is a significant milestone reflecting our determination to advance women's rights nationally and globally. We will expand opportunities, prevent violence, and promote women's economic empowerment and leadership. Our youth meanwhile represent not simply the future of Kiribas. We must provide them with education, employment, skills, technology, leadership opportunities and spaces where they can contribute and one of those spaces is sport."},{"t":828,"topic":"Micronian Games","text":"Gilibas will lost the 2030 Micronian Games which we intend to use to leave a lasting legacy for our young people. We invite our regional and international partners to join us in this endeavor for kibbas on peace and security. Mr. President, Kilibus is a peaceful nation. Yet distance does not make a difference to the suffering caused by war and conflicts elsewhere. The people of every nation deserve peace. We reaffirm that disputes must be resolved peacefully in accordance with the international law and the principles of the United Nations chart. For highland nations such as Gibbus, respect for international law is fundamental to our security, sovereignty, and stability of the international system."},{"t":899,"topic":"Nuclear disarmament","text":"Gibbus is proud to contribute in our own way to international peace and security through the service of our police officers under the United Nations flag. For Kibas, this is an expression of our belief that even the smallest country can contribute to global peace. For Pacific people, the consequences of nuclear weapons are not mis merely historical. Our region bears the human and environmental legacy of nuclear testing. uh state parties to the treaty on the prohibition of nuclear weapons. We remain committed to advancing the treaties and human humanitarian objectives and establishing an international trust fund for nuclear weapons victims. As co-chairs with Kazakhstan of the recent international meeting on victim assistance and environmental remediation, we thank the Secretary General for convening this important meeting and for keeping the needs of affected communities at the center of our collective efforts."},{"t":973,"topic":"Micronesia infrastructure","text":"Peace and security must also keep pace with emerging threats in the digital domain. The his Micronian cable landed in Tarawa last year connecting Gilibas with NU and the federated state of Micronia transforming our connectivity and digital environment. However, it also creates vulnerabilities with limited redundancy and technical capacity. Island states face threats including cyber crime, critical infrastructure attacks and ransomware and online harms that can undermine security and development. Your excellencies Gibbus comes to this assembly not simply to speak of the challenges we face. We come here. We come to speak of the future we choose. Allow me to to close, Mr."},{"t":1036,"topic":"Ceremony","text":"President, by bestowing upon the United Nations and all its members and all its staff our traditional blessings of the Maui, the Roy meaning abundant health, peace and prosperity. I thank you. On behalf of the assembly, I wish to thank the president and minister of foreign affairs and immigration of the republic of Kibati."}],"compare":[{"topic":"Climate Change","share":0.1409,"mean":0.0423,"rank":19,"others":77},{"topic":"Ocean Governance","share":0.1398,"mean":0.0061,"rank":2,"others":16},{"topic":"UN & its reform","share":0.1322,"mean":0.2051,"rank":128,"others":170},{"topic":"Nuclear Disarmament","share":0.0773,"mean":0.0037,"rank":4,"others":9},{"topic":"Sustainable Development","share":0.0766,"mean":0.0121,"rank":10,"others":28},{"topic":"Sports development","share":0.0732,"mean":0.0004,"rank":1,"others":1},{"topic":"Micronesia","share":0.0662,"mean":0.0,"rank":1,"others":0}]};
